def test_R8_action_convene_meeting_enforcement():
    """
    Test that convene meeting action exists and is registered with proper rule.
    Agent knows their responsibility to convene meetings for penalties.
    """
    # Verify action exists in institution.json
    institution = json.loads(Path("state/institution.json").read_text())
